        id: base.id ||
            `webmcp-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`,
        connectedAt: base.connectedAt ?? new Date().toISOString(),
        url: base.url ||
            (typeof window !== "undefined" ? window.location.href : undefined),
        ...base,
